Bg.Size = UDim2.new(1, 0, 1, 0)
Bg.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
Bg.BackgroundTransparency = 1
Bg.BorderSizePixel = 0
Bg.ClipsDescendants = true
Bg.Parent = Gui

-- ========== 中心容器 ==========
local Center = Instance.new("Frame")
Center.Size = UDim2.new(1, 0, 1, 0)
Center.BackgroundTransparency = 1
Center.Parent = Bg

-- 辅助函数
local function makeLabel(props)
    local lbl = Instance.new("TextLabel")
    lbl.AnchorPoint = Vector2.new(0.5, 0.5)
    lbl.BackgroundTransparency = 1
    lbl.TextXAlignment = Enum.TextXAlignment.Center
    lbl.TextYAlignment = Enum.TextYAlignment.Center
    lbl.Font = Enum.Font.SourceSansBold
    lbl.TextTransparency = 1
    for k, v in pairs(props) do lbl[k] = v end
    return lbl
end

-- 渐变文字
local function gradientText(text, c1, c2, c3)
    local result = ""
    for i = 1, #text do
        local t = (i - 1) / math.max(1, #text - 1)
        local r = c1.R*(1-t)^2 + c2.R*2*(1-t)*t + c3.R*t^2
        local g = c1.G*(1-t)^2 + c2.G*2*(1-t)*t + c3.G*t^2
        local b = c1.B*(1-t)^2 + c2.B*2*(1-t)*t + c3.B*t^2
        result = result .. string.format('<font color="#%02X%02X%02X">%s</font>',
            math.floor(r*255), math.floor(g*255), math.floor(b*255), text:sub(i,i))
    end
    return result
end

-- 缩放动画
local function scaleIn(obj, size, dur)
    return TweenService:Create(obj, TweenInfo.new(dur, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {
        Size = UDim2.new(0, size.X, 0, size.Y),
        TextTransparency = 0
    })
end

local function scaleOut(obj, dur)
    return TweenService:Create(obj, TweenInfo.new(dur, Enum.EasingStyle.Quad, Enum.EasingDirection.In), {
        Size = UDim2.new(0, 0, 0, 0),
        TextTransparency = 1
    })
end

